const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
yesterday.setHours(12, 0, 0, 0);
yesterday.setMilliseconds(0);
const ingested_at = yesterday.toISOString();
const store = 'store_1';
const allRows = [];
for (const item of $input.all()) {
  const subs = item.json.data || [];
  for (const sub of subs) {
    const line = (sub.lines && sub.lines.length > 0) ? sub.lines[0] : {};
    allRows.push({
      ingested_at, store,
      subscription_id: sub.id || null,
      shopify_id: sub.shopifyId || null,
      origin_order_shopify_id: sub.originOrderShopifyId || null,
      created_at: sub.createdAt || null,
      updated_at: sub.updatedAt || null,
      status: sub.status || null,
      cancellation_reason: sub.cancellationReason || null,
      cancellation_comment: sub.cancellationComment || null,
      completed_orders_count: sub.completedOrdersCount || 0,
      paused_at: sub.pausedAt || null,
      cancelled_at: sub.cancelledAt || null,
      total_line_item_price: sub.totalLineItemPrice || 0,
      total_line_item_discounted_price: sub.totalLineItemDiscountedPrice || 0,
      delivery_price: sub.deliveryPrice || 0,
      currency_code: sub.currencyCode || null,
      billing_interval: (sub.billingPolicy || {}).interval || null,
      billing_interval_count: (sub.billingPolicy || {}).intervalCount || null,
      next_billing_date_epoch: sub.nextBillingDateEpoch || null,
      last_payment_status: sub.lastPaymentStatus || null,
      is_prepaid: sub.isPrepaid || false,
      is_marked_for_cancellation: sub.isMarkedForCancellation || false,
      customer_id: (sub.customer || {}).id || null,
      customer_shopify_id: (sub.customer || {}).shopifyId || null,
      customer_email: (sub.customer || {}).email || null,
      country_code: (sub.shippingAddress || {}).countryCode || null,
      province_code: (sub.shippingAddress || {}).provinceCode || null,
      product_shopify_id: line.productShopifyId || null,
      variant_shopify_id: line.variantShopifyId || null,
      product_title: line.productTitle || null,
      variant_title: line.variantTitle || null,
      sku: line.sku || null,
      price: parseFloat(line.price) || 0,
      discounted_price: parseFloat(line.discountedPrice) || 0,
      base_price: parseFloat(line.basePrice) || 0,
      quantity: line.quantity || 0,
      delivery_method: (sub.deliveryMethod || {}).title || null
    });
  }
}
return allRows.map(row => ({ json: row }));

